"""Taskfile location helpers, independent of the YAML loader."""
from pathlib import Path

NAMES = (
    "Taskfile.yml", "taskfile.yml", "Taskfile.yaml", "taskfile.yaml",
    "Taskfile.dist.yml", "taskfile.dist.yml", "Taskfile.dist.yaml", "taskfile.dist.yaml",
)


def find_taskfile(directory='.', explicit=None, global_file=False, home=None):
    """Return (path, execution_root), or (None, directory) if not found.

    Automatic lookup walks toward filesystem root, matching Task's behavior.
    Explicit paths are resolved relative to the selected working directory.
    """
    start = Path(home if global_file and home else directory).expanduser().resolve()
    if explicit is not None:
        if explicit == '-':
            return '-', str(start)
        p = Path(explicit).expanduser()
        if not p.is_absolute():
            p = start / p
        if p.is_dir():
            for name in NAMES:
                candidate = p / name
                if candidate.is_file():
                    return str(candidate.resolve()), str(p.resolve())
        return str(p.resolve()), str(p.resolve().parent)
    current = start
    while True:
        for name in NAMES:
            candidate = current / name
            if candidate.is_file():
                return str(candidate.resolve()), str(current)
        if current.parent == current:
            break
        current = current.parent
    return None, str(start)
"""Load Task configuration files and TASK_* environment overrides."""
import os
from pathlib import Path


BOOLS = {
    'verbose': 'TASK_VERBOSE', 'silent': 'TASK_SILENT', 'color': 'TASK_COLOR',
    'disable-fuzzy': 'TASK_DISABLE_FUZZY', 'failfast': 'TASK_FAILFAST',
    'dry': 'TASK_DRY', 'assume-yes': 'TASK_ASSUME_YES',
    'interactive': 'TASK_INTERACTIVE',
}


def _scalar(value):
    value = value.split(' #', 1)[0].strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        value = value[1:-1]
    low = value.lower()
    if low in ('true', 'yes', 'on'): return True
    if low in ('false', 'no', 'off'): return False
    if low in ('null', '~', ''): return None
    try: return int(value)
    except ValueError: return value


def _read_config(path):
    """Read the common flat option subset of Task's YAML config."""
    out = {}
    try: lines = Path(path).read_text(encoding='utf-8').splitlines()
    except OSError: return out
    for line in lines:
        if not line.strip() or line.lstrip().startswith('#') or line[0].isspace():
            continue
        if ':' not in line: continue
        key, value = line.split(':', 1)
        out[key.strip().replace('_', '-')] = _scalar(value)
    return out


def load_config(cwd=None, environ=None):
    """Return merged .taskrc options, then overridden by TASK_* values.

    Current/parent directories have increasing priority, followed by HOME and
    XDG config as documented by Task.
    """
    cwd = Path(cwd or os.getcwd()).resolve()
    env = os.environ if environ is None else environ
    result = {}
    xdg = Path(env.get('XDG_CONFIG_HOME', str(Path(env.get('HOME', str(Path.home()))) / '.config'))) / 'task'
    for base in (xdg, Path(env.get('HOME', str(Path.home())))):
        for name in ('taskrc.yml', 'taskrc.yaml', '.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(base / name))
    for directory in reversed((cwd, *cwd.parents)):
        for name in ('.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(directory / name))
    for key, envkey in BOOLS.items():
        if envkey in env:
            val = env[envkey].lower()
            result[key] = val in ('true', '1', 'yes', 'on')
    if 'TASK_CONCURRENCY' in env:
        try: result['concurrency'] = int(env['TASK_CONCURRENCY'])
        except ValueError: pass
    return result
"""Task information modes (summary and status checks)."""
import os
import subprocess
import sys
import re


def _template(value, vars):
    def replace(match):
        key = match.group(1)
        return str(vars.get(key, os.environ.get(key, "")))
    return re.sub(r"{{\s*\.([A-Za-z_][\w]*)\s*}}", replace, str(value))


def _commands(task):
    if isinstance(task, str):
        return [task]
    if isinstance(task, list):
        return task
    task = task or {}
    cmds = task.get("cmds", []) or []
    if not cmds and task.get("cmd"):
        cmds = [task["cmd"]]
    return cmds


def show_summary(config, name, taskfile="", cwd=None):
    """Print the reference-style summary for one normalized task."""
    tasks = config.get("tasks") or {}
    task = tasks.get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    obj = task if isinstance(task, dict) else {}
    vars = dict(config.get("vars") or {})
    print(f"task: {name}")
    print()
    desc = obj.get("summary") or obj.get("desc", "")
    if desc:
        print(_template(desc, vars))
    print()
    if vars:
        print("vars:")
        for key, value in vars.items():
            # Task's summary uses YAML-compatible quoted strings for scalars.
            if isinstance(value, str):
                val = '"' + value.replace('\\', '\\\\').replace('"', '\\"') + '"'
            elif value is None:
                val = "null"
            elif isinstance(value, bool):
                val = str(value).lower()
            else:
                val = str(value)
            print(f"  {key}: {val}")
        print()
    cmds = _commands(task)
    rendered = []
    for command in cmds:
        if isinstance(command, dict):
            command = command.get("cmd", "")
        if command:
            rendered.append(_template(command, vars))
    if rendered:
        print("commands:")
        for command in rendered:
            print(f" - {command}")
    return 0


def check_status(config, name, cwd=None):
    """Return success only when status commands all report the task current."""
    task = (config.get("tasks") or {}).get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    task = task if isinstance(task, dict) else {}
    checks = task.get("status") or []
    if isinstance(checks, str):
        checks = [checks]
    env = os.environ.copy()
    for key, value in (config.get("vars") or {}).items():
        env[str(key)] = str(value)
    for check in checks:
        try:
            if subprocess.run(str(check), shell=True, cwd=cwd, env=env,
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
                break
        except OSError:
            break
    else:
        if checks:
            return 0
    print(f'task: Task "{name}" is not up-to-date', file=sys.stderr)
    return 1

