def run_init(directory='.', filename=None):
    """Create a Taskfile at filename. Return Task's process exit code."""
    custom = filename is not None
    requested = filename if custom else 'Taskfile.yml'
    path = Path(requested)
    if not path.is_absolute(): path = Path(directory) / path
    display = os.path.normpath(str(requested))
    directory_target = path.is_dir()
    check_directory = path if directory_target else Path(directory)
    if directory_target:
        path = path / 'Taskfile.yml'
        display = os.path.normpath(os.path.join(display, 'Taskfile.yml'))
    existing = (
        'Taskfile.yml', 'Taskfile.yaml', 'taskfile.yml', 'taskfile.yaml',
        'Taskfile.dist.yml', 'Taskfile.dist.yaml',
        'taskfile.dist.yml', 'taskfile.dist.yaml',
    )
